  1 │ /**
  2 │  * Shared rules for text that becomes a unit's input: which workspace paths may never be read into it, how the
  3 │  * candidate diff is built without them, and the credential redaction applied before it is persisted or prompted.
  4 │  */
  5 │ import * as fs from "node:fs";
  6 │ import * as os from "node:os";
  7 │ import * as path from "node:path";
  8 │ import { execFileSync } from "node:child_process";
  9 │ import { createHash } from "node:crypto";
 10 │ import { SecurityManager } from "../security.js";
 11 │ import { MAX_SPECIALIST_INPUT_CHARS } from "./specialist_profiles.js";
 12 │ import { redactForPersistence } from "./persistence_protection.js";
 13 │ 
 14 │ /**
 15 │  * Whether a workspace-relative path is off limits as input text: protected by the workspace security policy (the one
 16 │  * read_file applies), or inside Nexus's own state directory (`.nexus`, compared case-insensitively because the
 17 │  * filesystem may be).
 18 │  */
 19 │ export function inputPathProtection(security: SecurityManager, relative: string): string | undefined {
 20 │   const segments = relative.split(/[\\/]/).map((segment) => segment.toLowerCase());
 21 │   if (segments.includes(".nexus")) return "inside .nexus";
 22 │   const check = security.isPathProtected(relative);
 23 │   return check.protected ? (check.reason ?? "protected by the security policy") : undefined;
 24 │ }
 25 │ 
 26 │ /**
 27 │  * Global options for every git call that reads the workspace for a prompt. Rendering is pinned, and nothing the
 28 │  * repository configures may run in this process: no fsmonitor hook, no hooks, no replace objects, no system or
 29 │  * per-user attributes, no automatic gc. Clean/smudge filters are kept out by the attribute source below.
 30 │  */
 31 │ export const GIT_SAFE = [
 32 │   "--no-replace-objects",
 33 │   "-c", "core.quotepath=false", "-c", "diff.noprefix=false", "-c", "diff.mnemonicPrefix=false", "-c", "diff.external=", "-c", "core.pager=cat",
 34 │   "-c", "core.fsmonitor=false", "-c", "core.hooksPath=/dev/null", "-c", "core.attributesFile=/dev/null", "-c", "core.untrackedCache=false",
 35 │   "-c", "gc.auto=0", "-c", "maintenance.auto=false",
 36 │ ];
 37 │ /** Git's empty tree: as GIT_ATTR_SOURCE (Git 2.40+) it means the worktree's .gitattributes assign no attribute. */
 38 │ const EMPTY_TREE = "4b825dc642cb6eb9a060e54bf8d69288fbee4904";
 39 │ 
 40 │ /**
 41 │  * The environment for those calls: inherited GIT_* variables (GIT_DIR, GIT_INDEX_FILE, GIT_CONFIG_PARAMETERS, ...)
 42 │  * are dropped, system config and system attributes are ignored, replace objects are off, and attributes come from
 43 │  * a tree of the worktree's own .gitattributes files with every filter and diff assignment removed (the empty tree when
 44 │  * there are none), so `text`/`eol` normalization still applies but no driver does. `$GIT_DIR/info/attributes` still
 45 │  * applies (and on Git older than 2.40 so do the worktree's .gitattributes), so a filter or diff driver assigned that
 46 │  * way is refused before any command could invoke it.
 47 │  */
 48 │ export function safeGitEnv(indexFile: string | undefined, attrs?: { tree: string; objects: string }): NodeJS.ProcessEnv {
 49 │   const env: NodeJS.ProcessEnv = {};
 50 │   for (const [key, value] of Object.entries(process.env)) if (!key.startsWith("GIT_")) env[key] = value;
 51 │   return {
 52 │     ...env, ...(indexFile ? { GIT_INDEX_FILE: indexFile } : {}), GIT_CONFIG_NOSYSTEM: "1", GIT_ATTR_NOSYSTEM: "1", GIT_NO_REPLACE_OBJECTS: "1",
 53 │     GIT_ATTR_SOURCE: attrs?.tree ?? EMPTY_TREE, GIT_OPTIONAL_LOCKS: "0",
 54 │     ...(attrs ? { GIT_ALTERNATE_OBJECT_DIRECTORIES: attrs.objects } : {}),
 55 │   };
 56 │ }
 57 │ 
 58 │ /** Drops every `filter` and `diff` assignment (and unset/unspecify forms) from .gitattributes text, macros included. */
 59 │ export function withoutDrivers(text: string): string {
 60 │   return text.split("\n").map((line) => {
 61 │     const trimmed = line.trim();
 62 │     if (!trimmed || trimmed.startsWith("#")) return line;
 63 │     const head = /^("(?:[^"\\]|\\.)*"|\S+)(\s+|$)/.exec(trimmed);
 64 │     if (!head) return line;
 65 │     const rest = trimmed.slice(head[0].length).split(/\s+/).filter(Boolean);
 66 │     return [head[1], ...rest.filter((token) => !/^[-!]?(filter|diff)(=|$)/.test(token))].join(" ");
 67 │   }).join("\n");
 68 │ }
 69 │ /**
 70 │  * The repository states the candidate diff and the debugger snapshot are built for, as one finite predicate over the
 71 │  * unit's own index and configuration. Inside it the scratch index (base tree, or a copy of the real index) plus the
 72 │  * worktree is a faithful picture of the candidate: every index entry is a plain stage-0 file or symlink whose
 73 │  * worktree state git actually checks, and file modes and symlinks are real on the filesystem. Outside it the answer
 74 │  * would depend on flags that tell git not to look at the worktree (assume-unchanged, skip-worktree, sparse checkout),
 75 │  * on modes the filesystem cannot report (`core.filemode=false`, `core.symlinks=false`), on case folding, on gitlinks
 76 │  * (submodules: the diff shows only the pointer), or on an unresolved merge, so it is refused with a reason instead of
 77 │  * a guess. Not refused, and covered by tests: detached HEAD, linked worktrees, untracked and ignored files,
 78 │  * intent-to-add entries, renames and copies, symlinks, a merge or rebase in progress once resolved in the index.
 79 │  * `run` is a pinned git call against the repository's own index (never written).
 80 │  */
 81 │ export type SnapshotSupport = { ok: true } | { unsupported: string };
 82 │ export function snapshotSupport(run: (args: string[]) => string): SnapshotSupport {
 83 │   const config = new Map<string, string>();
 84 │   try {
 85 │     for (const line of run(["config", "--type=bool", "--get-regexp", "^core\\.(filemode|symlinks|ignorecase|sparsecheckout|sparsecheckoutcone)$"]).split("\n")) {
 86 │       const [key, value] = line.split(" ");
 87 │       if (key) config.set(key.toLowerCase(), value);
 88 │     }
 89 │   } catch (err: any) {
 90 │     if (err?.status !== 1) throw err; // 1 = none of them is set: every default is inside the domain
 91 │   }
 92 │   const refuse = (what: string, fix: string): SnapshotSupport => ({ unsupported: `${what}; ${fix}` });
 93 │   if (config.get("core.filemode") === "false") return refuse("core.filemode is false, so file modes are not read from disk", "set core.filemode=true or pass explicit inputs");
 94 │   if (config.get("core.symlinks") === "false") return refuse("core.symlinks is false, so symlinks are checked out as files", "set core.symlinks=true or pass explicit inputs");
 95 │   if (config.get("core.ignorecase") === "true") return refuse("core.ignorecase is true (a case-insensitive filesystem), so paths cannot be matched exactly", "pass explicit inputs");
 96 │   if (config.get("core.sparsecheckout") === "true") return refuse("a sparse checkout is enabled", "run `git sparse-checkout disable` or pass explicit inputs");
 97 │   const unmerged = new Set<string>();
 98 │   for (const entry of run(["ls-files", "-s", "-z"]).split("\0")) {
 99 │     const m = /^(\d{6}) [0-9a-f]+ (\d)\t([\s\S]*)$/.exec(entry);
100 │     if (!m) continue;
101 │     if (m[1] === "160000") return refuse(`${m[3].slice(0, 80)} is a submodule (gitlink): only its pointer would be shown, not its content`, "pass explicit inputs");
102 │     if (m[2] !== "0") unmerged.add(m[3]);
103 │   }
104 │   if (unmerged.size) return refuse(`${unmerged.size} path(s) have unresolved merge conflicts (for example ${[...unmerged][0].slice(0, 80)})`, "resolve them or pass explicit inputs");
105 │   for (const entry of run(["ls-files", "-v", "-z", "--cached"]).split("\0")) {
106 │     if (!entry || entry[0] === "H") continue;
107 │     const tag = entry[0];
108 │     const file = entry.slice(2).slice(0, 80);
109 │     if (tag === "S" || tag === "s") return refuse(`${file} is marked skip-worktree (sparse checkout), so git does not look at its worktree state`, "run `git update-index --no-skip-worktree` or pass explicit inputs");
110 │     if (tag >= "a" && tag <= "z") return refuse(`${file} is marked assume-unchanged, so git does not look at its worktree state`, "run `git update-index --no-assume-unchanged` or pass explicit inputs");
111 │     if (tag === "M") continue; // unmerged entries are reported above
112 │     return refuse(`${file} has index state '${tag}' that is not supported`, "pass explicit inputs");
113 │   }
114 │   return { ok: true };
115 │ }
