117 │ const DIFF_FLAGS =["--no-color", "--no-ext-diff", "--no-textconv", "--no-renames", "--relative"];
118 │ const MAX_DIFF_PATHS = 2_000;
119 │ const GIT_MAX_BUFFER = 4 * 1024 * 1024;
120 │ /** Path listings scale with the repository, not the change, so they get room for very large repositories. */
121 │ const LISTING_MAX_BUFFER = 256 * 1024 * 1024;
122 │ /** Paths per `check-attr` call, so its output stays small whatever the repository's size. */
123 │ const ATTR_BATCH = 1_000;
124 │ 
125 │ /**
126 │  * Refuses (returns why) when a filter or diff driver still applies to any of `files` under the pinned attribute
127 │  * source, which only `$GIT_DIR/info/attributes` (or a worktree .gitattributes on Git before 2.40) can still assign.
128 │  * `run` is a pinned git call that takes stdin. Batched so a repository's size never becomes a failure.
129 │  */
130 │ export function driverRefusal(run: (args: string[], input: string) => string, files: string[]): string | undefined {
131 │   for (let start = 0; start < files.length; start += ATTR_BATCH) {
132 │     const batch = files.slice(start, start + ATTR_BATCH);
133 │     const checked = run(["check-attr", "-z", "--stdin", "filter", "diff"], `${batch.join("\0")}\0`).split("\0");
134 │     for (let i = 0; i + 2 < checked.length; i += 3) {
135 │       const [file, name, value] = [checked[i], checked[i + 1], checked[i + 2]];
136 │       const safe = value === "unspecified" || value === "unset" || (name === "diff" && value === "set");
137 │       if (!safe) return `a ${name} driver ('${value}') applies to ${file.slice(0, 80)} outside the worktree's .gitattributes; it is not run`;
138 │     }
139 │   }
140 │   return undefined;
141 │ }
142 │ 
143 │ /** Ignored trees (node_modules, build output) scale with the repository, not the change: about 6 s per 90k files. */
144 │ const IGNORED_LISTING_TIMEOUT_MS = 180_000;
145 │ const SOURCE_FILE_MAX = 4 * 1024 * 1024;
146 │ const SOURCE_TOTAL_MAX = 64 * 1024 * 1024;
147 │ const ADDED_FILE_MAX = 16 * 1024 * 1024;
148 │ const SIGNIFICANT_LINE_MIN = 8;
149 │ 
150 │ /**
151 │  * The content of the protected files present in the workspace (tracked, untracked or ignored), for recognising a new
152 │  * file that carries it. A new file is carried when it equals a protected file exactly (whatever its size) or shares a
153 │  * significant line with one: a trimmed, non-comment line of at least 8 characters. Files inside `.nexus` take part by
154 │  * exact content only (their lines are structural). When the sources cannot all be read within the limits, every new
155 │  * file counts as carried: nothing is kept because it could not be compared.
156 │  */
157 │ function protectedContent(sources: Array<{ root: string; file: string }>): { carriedBy(dir: string, relative: string): boolean } {
158 │   const hashes = new Set<string>();
159 │   const lines = new Set<string>();
160 │   let complete = true;
161 │   let total = 0;
162 │   for (const { root, file } of sources) {
163 │     const structural = file.split(/[\\/]/).some((seg) => seg.toLowerCase() === ".nexus");
164 │     let size: number;
165 │     try {
166 │       const st = fs.lstatSync(path.join(root, file));
167 │       if (!st.isFile()) continue;
168 │       size = st.size;
169 │     } catch { continue; }
170 │     // A large `.nexus` file (a flight log) is not a credential source: it is left out instead of failing every new file closed.
171 │     if (structural && size > SOURCE_FILE_MAX) continue;
172 │     if (!structural) total += size;
173 │     if (size > SOURCE_FILE_MAX || total > SOURCE_TOTAL_MAX) { complete = false; continue; }
174 │     let data: Buffer;
175 │     try { data = fs.readFileSync(path.join(root, file)); } catch { complete = false; continue; }
176 │     hashes.add(createHash("sha256").update(data).digest("hex"));
177 │     if (structural) continue;
178 │     for (const line of significantLines(data)) lines.add(line);
179 │   }
180 │   return {
181 │     carriedBy(dir: string, relative: string): boolean {
182 │       if (!complete) return true;
183 │       if (hashes.size === 0 && lines.size === 0) return false;
184 │       let data: Buffer;
185 │       try {
186 │         const st = fs.lstatSync(path.join(dir, relative));
187 │         if (!st.isFile()) return false;
188 │         if (st.size > ADDED_FILE_MAX) return true;
189 │         data = fs.readFileSync(path.join(dir, relative));
190 │       } catch { return true; }
191 │       if (hashes.has(createHash("sha256").update(data).digest("hex"))) return true;
192 │       for (const line of significantLines(data)) if (lines.has(line)) return true;
193 │       return false;
194 │     },
195 │   };
196 │ }
197 │ 
198 │ function significantLines(data: Buffer): string[] {
199 │   return data.toString("latin1").split("\n").map((l) => l.trim())
200 │     .filter((l) => l.length >= SIGNIFICANT_LINE_MIN && !l.startsWith("#") && !l.startsWith("//") && /[A-Za-z0-9]/.test(l));
201 │ }
202 │ 
203 │ /**
204 │  * The attribute source for a diff: the worktree's .gitattributes files with filter and diff assignments removed, as a
205 │  * tree in a private object directory (nothing is written to the repository). Undefined when there are none.
206 │  */
207 │ export function attributesTree(root: string, scratch: string, files: string[]): { tree: string; objects: string } | undefined {
208 │   const sources = files.filter((f) => path.posix.basename(f) === ".gitattributes").flatMap((f) => {
209 │     try {
210 │       const full = path.join(root, f);
211 │       const st = fs.lstatSync(full);
212 │       return st.isFile() && st.size <= 1024 * 1024 ? [{ file: f, text: withoutDrivers(fs.readFileSync(full, "utf8")) }] : [];
213 │     } catch { return []; }
214 │   });
215 │   if (!sources.length) return undefined;
216 │   const objects = path.join(scratch, "attr-objects");
217 │   fs.mkdirSync(objects);
218 │   const env = { ...safeGitEnv(path.join(scratch, "attr-index")), GIT_OBJECT_DIRECTORY: objects };
219 │   const run = (args: string[], input?: string) => execFileSync("git", [...GIT_SAFE, ...args], { cwd: root, env, encoding: "utf8", stdio: [input === undefined ? "ignore" : "pipe", "pipe", "pipe"], timeout: 30_000, ...(input === undefined ? {} : { input }) });
220 │   const entries = sources.map(({ file, text }) => `100644 ${run(["hash-object", "-w", "--stdin"], text).trim()}\t${file}\0`);
221 │   run(["update-index", "--add", "-z", "--index-info"], entries.join(""));
222 │   return { tree: run(["write-tree"]).trim(), objects };
223 │ }
224 │ 
225 │ /**
226 │  * The candidate diff against `base` (HEAD when absent), for every unit that is shown one: review units and the
227 │  * security reviewer. No repository-configured command runs while it is built (see GIT_SAFE and safeGitEnv); a
228 │  * filter or diff driver that would still apply makes it fail. It is built from the changed paths and never from parsing diff text: the changed paths come from
229 │  * NUL-separated git output with rendering options pinned, the protected ones (the read_file policy, `.nexus`) are
230 │  * removed, and the diff is then requested for the remaining paths only (literal pathspecs), so a protected file cannot
231 │  * appear in it whatever the repository's diff settings. A rename or copy with either side protected drops both sides
232 │  * (the body of a file renamed out of a protected path is still its content).
233 │  *
234 │  * Untracked files are compared through a scratch index (the base tree plus intent-to-add entries for every untracked
235 │  * file, never the repository's own index), so git's rename detection pairs an unstaged move of a protected file with
236 │  * its new name instead of showing that name as an unrelated new file. Rename and copy detection stop at git's
237 │  * similarity threshold (and `--find-copies-harder` makes an untouched tracked protected file a copy source), so when
238 │  * any protected path changed (moved, deleted, edited or added), every added file is omitted too and counted in
239 │  * `omittedNew`: a protected file moved and rewritten, or one whose lines were copied out, may otherwise reach the diff
240 │  * as an innocent new file. Independently of git's heuristics, an added file is omitted (and counted the same way) when
241 │  * it equals a protected file present in the workspace, tracked, untracked or ignored, or shares a significant line
242 │  * with one (see `protectedContent`); that covers `cp .env notes.txt` and a partial copy of any size.
243 │  * Limits of that comparison, where credential redaction is the only guard: lines pasted from a protected file into a
244 │  * file that already existed at the base (modified files are not line-compared); any re-formatting of a protected
245 │  * file's lines (quoting, a changed separator, values only, re-encoding), because a line matches only exactly once
246 │  * trimmed and is at least 8 characters; and a protected file whose lines are all shorter than that, which is caught
247 │  * only by an exact whole-file match. The trade-off is over-omission: a new file sharing a common line (such as
248 │  * NODE_ENV=development) with any protected file in the workspace, an ignored `.env*` included, is omitted and noted.
249 │  * The pass listing ignored files takes up to IGNORED_LISTING_TIMEOUT_MS (about 6 s per 90k ignored files); a tree too
250 │  * large for it fails closed with an error rather than being trusted.
251 │  * Any git failure or an unmanageable path count returns an error: nothing is ever kept because it could not be
252 │  * classified.
253 │  */
254 │ export interface CandidateDiff { base: string; diff: string; omitted: number; omittedNew: number; omittedNested: number }
255 │ export function candidateDiff(workspace: string, base: string | undefined, policyWorkspace?: string): CandidateDiff | { error: string } {
256 │   const root = path.resolve(workspace);
257 │   let scratch: string | undefined;
258 │   let attrs: { tree: string; objects: string } | undefined;
259 │   // `ownIndex` reads the repository's own index (never written: only listed); everything else uses the scratch index.
260 │   const git = (args: string[], options: { okExit?: number[]; input?: string; maxBuffer?: number; ownIndex?: boolean; timeoutMs?: number } = {}): string => {
261 │     try {
262 │       return execFileSync("git", [...GIT_SAFE, ...args], {
263 │         cwd: root, env: safeGitEnv(options.ownIndex ? undefined : path.join(scratch!, "index"), attrs), encoding: "utf8", stdio: [options.input === undefined ? "ignore" : "pipe", "pipe", "pipe"],
264 │         timeout: options.timeoutMs ?? 30_000, maxBuffer: options.maxBuffer ?? GIT_MAX_BUFFER, ...(options.input === undefined ? {} : { input: options.input }),
265 │       });
266 │     } catch (err: any) {
267 │       if (typeof err?.status === "number" && options.okExit?.includes(err.status) && typeof err.stdout === "string") return err.stdout;
268 │       throw err;
269 │     }
270 │   };
271 │   try {
272 │     scratch = fs.mkdtempSync(path.join(os.tmpdir(), "nexus-candidate-index-"));
273 │     // The policy is the operator's (their workspace), not whatever a unit's own worktree holds: an untracked
274 │     // .nexus-security.json never reaches a worktree.
275 │     const security = new SecurityManager(policyWorkspace ?? root);
276 │     // A base read from persisted JSON is resolved as a commit before use: a value shaped like an option is refused.
277 │     const support = snapshotSupport((args) => git(args, { ownIndex: true }));
278 │     if ("unsupported" in support) return { error: `automatic inputs are not available for this repository state: ${support.unsupported}` };
279 │     const commit = git(["rev-parse", "--verify", "--end-of-options", `${base ?? "HEAD"}^{commit}`]).trim();
280 │     git(["read-tree", "--end-of-options", commit]);
281 │     const listing = (args: string[], ownIndex = false, timeoutMs?: number) => git(["ls-files", "-z", ...args], { maxBuffer: LISTING_MAX_BUFFER, ownIndex, timeoutMs }).split("\0").filter(Boolean);
282 │     // New paths: untracked files git does not ignore, plus files tracked now but not at the base (a force-added file
283 │     // can match .gitignore and still be part of the candidate).
284 │     const atBase = new Set(listing([]));
285 │     // A path tracked since the base but already removed from disk is a deletion against nothing: it has no content to
286 │     // show, and git would reject it as a pathspec.
287 │     const onDisk = (p: string) => { try { fs.lstatSync(path.join(root, p)); return true; } catch { return false; } };
288 │     const ownIndex = new Set(listing([], true));
289 │     // Untracked, non-ignored entries, listed once. A directory entry (trailing slash) is an untracked nested git
290 │     // repository, which `git add` refuses: it is skipped and counted rather than failing every review.
291 │     const others = listing(["--others", "--exclude-standard"]);
292 │     const omittedNested = others.filter((p) => p.endsWith("/")).length;
293 │     const untracked = others.filter((p) => !p.endsWith("/"));
294 │     attrs = attributesTree(root, scratch, [...new Set([...untracked, ...ownIndex])]);
295 │     // A path tracked at the base but removed from the real index (`git rm --cached`) is part of the candidate as a
296 │     // deletion even when the file stays on disk: force it out of the scratch index too (its entry can match neither HEAD nor the worktree), and never re-add it as new.
297 │     const removed = [...atBase].filter((p) => !ownIndex.has(p));
298 │     if (removed.length) {
299 │       git(["--literal-pathspecs", "rm", "--cached", "--force", "--quiet", "--ignore-unmatch", "--pathspec-from-file=-", "--pathspec-file-nul"], { input: `${removed.join("\0")}\0` });
300 │     }
301 │     const removedSet = new Set(removed);
302 │     const added = new Set([
303 │       ...untracked.filter((p) => !removedSet.has(p)),
304 │       ...[...ownIndex].filter((p) => !atBase.has(p) && onDisk(p)),
305 │     ]);
306 │     if (added.size) {
307 │       git(["--literal-pathspecs", "add", "--force", "--intent-to-add", "--pathspec-from-file=-", "--pathspec-file-nul"], { input: `${[...added].join("\0")}\0` });
308 │     }
309 │     // Comparing worktree content runs a path's clean filter, so before any diff every path is checked for a filter or
310 │     // diff driver the stripped attribute source did not neutralise ($GIT_DIR/info/attributes, or a worktree
311 │     // .gitattributes on Git before 2.40); one that applies is refused, never run. The check is batched so the
312 │     // repository's size never turns into a failure.
313 │     const refusal = driverRefusal((args, input) => git(args, { input }), listing([]));
314 │     if (refusal) return { error: refusal };
315 │     // name-status with rename detection (no limit on the exhaustive pass), only to learn which paths belong together.
316 │     const tokens = git(["diff", "--name-status", "-z", "-M", "-C", "--find-copies-harder", "-l0", "--relative", "--no-ext-diff", "--no-textconv", "--end-of-options", commit, "--"], { maxBuffer: LISTING_MAX_BUFFER }).split("\0");
317 │     const groups: Array<{ status: string; paths: string[] }> = [];
318 │     for (let i = 0; i < tokens.length; ) {
319 │       const status = tokens[i++];
320 │       if (!status) continue;
321 │       const count = status[0] === "R" || status[0] === "C" ? 2 : 1;
322 │       const paths = tokens.slice(i, i + count);
323 │       i += count;
324 │       if (paths.length !== count || paths.some((p) => !p)) return { error: "git reported a changed path that could not be read" };
325 │       groups.push({ status, paths });
326 │     }
327 │     if (groups.length > MAX_DIFF_PATHS) return { error: `the change touches more than ${MAX_DIFF_PATHS} paths; scope it with explicit inputs` };
328 │     const isProtected = (group: { paths: string[] }) => group.paths.some((p) => inputPathProtection(security, p) !== undefined);
329 │     const protectedChanged = groups.some(isProtected);
330 │     // Git's copy detection stops at its similarity threshold and never sees an ignored protected file, so an added file
331 │     // is also compared with the content of every protected file present in the workspace.
332 │     const ignored = listing(["--others", "--ignored", "--exclude-standard"], false, IGNORED_LISTING_TIMEOUT_MS).filter((p) => !p.endsWith("/"));
333 │     const isolated = path.resolve(policyWorkspace ?? root) !== root;
334 │     const protectedSources = [...new Set([...atBase, ...ownIndex, ...untracked, ...ignored])]
335 │       .filter((p) => inputPathProtection(security, p) !== undefined).map((file) => ({ root, file }));
336 │     // A unit's worktree lacks the operator's untracked and ignored secrets (.env), so those are compared too.
337 │     if (isolated) {
338 │       const operator = path.resolve(policyWorkspace!);
339 │       // Tracked, untracked and ignored files of the operator's repository. A failure (timeout, buffer) propagates: the
340 │       // comparison is never silently skipped.
341 │       for (const extra of [[], ["--ignored"]]) {
342 │         const listed = execFileSync("git", [...GIT_SAFE, "ls-files", "-z", "--cached", "--others", ...extra, "--exclude-standard"], {
343 │           cwd: operator, env: safeGitEnv(undefined), encoding: "utf8", stdio: ["ignore", "pipe", "pipe"], timeout: IGNORED_LISTING_TIMEOUT_MS, maxBuffer: LISTING_MAX_BUFFER,
344 │         }).split("\0").filter((p) => p && !p.endsWith("/") && inputPathProtection(security, p) !== undefined);
345 │         for (const file of listed) protectedSources.push({ root: operator, file });
346 │       }
347 │     }
348 │     const sources = protectedContent(protectedSources);
