 88 │     }
 89 │   } catch (err: any) {
 90 │     if (err?.status !== 1) throw err; // 1 = none of them is set: every default is inside the domain
 91 │   }
 92 │   const refuse = (what: string, fix: string): SnapshotSupport => ({ unsupported: `${what}; ${fix}` });
 93 │   if (config.get("core.filemode") === "false") return refuse("core.filemode is false, so file modes are not read from disk", "set core.filemode=true or pass explicit inputs");
 94 │   if (config.get("core.symlinks") === "false") return refuse("core.symlinks is false, so symlinks are checked out as files", "set core.symlinks=true or pass explicit inputs");
 95 │   if (config.get("core.ignorecase") === "true") return refuse("core.ignorecase is true (a case-insensitive filesystem), so paths cannot be matched exactly", "pass explicit inputs");
