136 │       const safe = value === "unspecified" || value === "unset" || (name === "diff" && value === "set");
137 │       if (!safe) return `a ${name} driver ('${value}') applies to ${file.slice(0, 80)} outside the worktree's .gitattributes; it is not run`;
138 │     }
139 │   }
140 │   return undefined;
