203 │ /**
204 │  * The attribute source for a diff: the worktree's .gitattributes files with filter and diff assignments removed, as a
205 │  * tree in a private object directory (nothing is written to the repository). Undefined when there are none.
206 │  */
207 │ export function attributesTree(root: string, scratch: string, files: string[]): { tree: string; objects: string } | undefined {
208 │   const sources = files.filter((f) => path.posix.basename(f) === ".gitattributes").flatMap((f) => {
209 │     try {
210 │       const full = path.join(root, f);
211 │       const st = fs.lstatSync(full);
212 │       return st.isFile() && st.size <= 1024 * 1024 ? [{ file: f, text: withoutDrivers(fs.readFileSync(full, "utf8")) }] : [];
213 │     } catch { return []; }
214 │   });
215 │   if (!sources.length) return undefined;
216 │   const objects = path.join(scratch, "attr-objects");
217 │   fs.mkdirSync(objects);
218 │   const env = { ...safeGitEnv(path.join(scratch, "attr-index")), GIT_OBJECT_DIRECTORY: objects };
